arguments.command:
curl -s -X PATCH "https://www.googleapis.com/calendar/v3/calendars/kenji-sato%40northwind.example/events/ev_named" -H "Authorization: Bearer <TOKEN>" -H "Content-Type: application/json" -d '{
  "start": {"dateTime": "2018-06-22T16:00:00-07:00", "timeZone": "America/Los_Angeles"},
  "end": {"dateTime": "2018-06-22T17:00:00-07:00", "timeZone": "America/Los_Angeles"}
}' | python3 -c "import json,sys; d=json.load(sys.stdin); print(d.get('summary'), '|', d.get('start'), '|', d.get('end'), '|', d.get('status'))"

